python3 -c "
import openpyxl
wb=openpyxl.load_workbook(\"documents/tax-reserve-schedule.xlsx\")
for ws in wb:
  print(\"##\",ws.title,ws.dimensions)
  for row in ws.iter_rows():
    vals=[f\"{c.coordinate}={c.value}\" for c in row if c.value is not None]
    if vals: print(\" | \".join(vals))
    for c in row:
      if c.comment: print(\"  COMMENT\",c.coordinate,c.comment.text)
"
